#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class BEveBasicTests {
  const string Root="D:/Project/LASTRAIL/",V2="unity.combat-b.direct-local.v2";
  static JObject Owned()=>(JObject)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/c3-owned-profile-observed-sql-test-20261001.json"))["profile"];
  static CombatDefinitionIndex Def()=>CombatDefinitionIntake.Read(JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/c3-definition-intake-20261001.json")));
  static JObject Q(long n,long d=1)=>new JObject{["numerator"]=n.ToString(),["denominator"]=d.ToString()};
  static JObject Entity(JObject p,string id)=>(JObject)((JArray)p["entities"]).Single(x=>(string)x["id"]==id);
  static BCombatFormation Formation(int count)=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,Enumerable.Range(0,count).Select(n=>new BCombatSlot("car"+n,n==0?"op_eve":null)));
  public static JObject Packet(int count=1){
   // Reuse the explicit non-operator LOCAL trial; construct Eve from her ORIGINAL profile, never rename Mira.
   var p=(JObject)typeof(BDirectAttackBasicLoopTests).GetMethod("Packet",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{count});
   var stats=((JArray)Owned()["operators"]).Single(o=>(string)o["operatorId"]=="op_eve")["permanentStats"];
   var rows=(JArray)p["entities"];foreach(var old in rows.Where(x=>(string)x["kind"]=="OPERATOR").ToArray())old.Remove();
   rows.Add(new JObject{["id"]="op_eve",["definitionId"]="op_eve",["kind"]="OPERATOR",["slot"]=0,["maxHp"]=stats["maxHp"].DeepClone(),["attack"]=stats["attack"].DeepClone(),["defense"]=Q((long)stats["defense"]),["basicIntervalMicroseconds"]=(long)stats["basicIntervalMs"]*1000,
    ["attackSources"]=new JArray(),["defenseSources"]=new JArray(),["effects"]=new JArray(),["weakening"]=new JArray(),["penetration"]=new JArray(),["reductions"]=new JObject{["equipment"]=new JArray(),["guardStance"]=new JArray(),["independent"]=new JArray()},["allowedTargets"]=new JArray("LOCAL_ENEMY")});
   p["version"]=V2;p["formation"]=Formation(count).Capture();p["geometry"]=new JArray(((JArray)p["geometry"]).Where(g=>(string)g["sourceId"]!="op_mira"&&(string)g["targetId"]!="op_mira").Select(g=>g.DeepClone()));
   ((JArray)p["geometry"]).Add(new JObject{["sourceId"]="op_eve",["targetId"]="enemy",["sourceSlot"]=0,["targetSlot"]=0,["distanceMm"]=1000,["maximumDistanceMm"]=2000,["observedTick"]=0,["validUntilTick"]=100000,["eligible"]=true});
   p["sourceEvidence"]=new JArray(new JObject{["sourceId"]="LOCAL_EVE_ORIGINAL_STATS_INDEPENDENT_NOT_STORED_PHYSICAL_OR_START",["sha256"]=BDirectAttackInput.Digest(Owned()).Substring(7)});return p;
  }
  public static BDirectAttackInput Input(JObject p=null){p=p??Packet();var o=Owned();return new BDirectAttackInput(p,BDirectAttackInput.Digest(p),Formation(((JArray)p["formation"]["slots"]).Count),o,BDirectAttackInput.Digest(o),Def());}
  static BDirectAttackBasicLoopBinding LoopBinding(BDirectAttackInput i,string type="BCB01"){
   var wrapper=JObject.Parse(File.ReadAllText(Root+"QA/CombatBMigration-20261002/BuffConsumer/original-definitions.json"));var defs=new BCarriageBuffDefinitions((string)typeof(BasicCombatSimulation).GetMethod("StableJson",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{wrapper}),BDirectAttackInput.Digest(wrapper).Substring(7));
   var d=new JObject{["version"]=BCarriageBuffDefinitions.Version,["accountId"]=i.OriginalAccountId,["selectionRevision"]=1,["rankRevision"]=1,["sourceStatus"]="ISOLATED_LOCAL_FIXTURE",["cars"]=new JArray(i.Formation.Slots.Select((slot,n)=>new JObject{["slot"]=n,["instanceId"]=slot.CarriageId,["carriageId"]="LOCAL_ORIGINAL_TRIAL_CAR_NOT_HTTP",["occupant"]=slot.IsCargo?new JObject{["kind"]="CARGO"}:new JObject{["kind"]="OPERATOR",["operatorId"]=slot.OperatorId},["type"]=type,["rank"]=1}))};
   var b=new JObject{["version"]=BDirectAttackBuffBinding.Version,["provenance"]="BOUNDED_LOCAL_NOT_FULL_RUN",["attackInputHash"]=i.OriginalHash,["definitionHash"]=defs.Hash,["departure"]=d,["initial"]=new JObject{["contextId"]="LOCAL_EVE_BASIC_TRIAL_NOT_STORED",["mode"]="EXTERIOR",["cars"]=new JArray(i.Formation.Slots.Select((slot,n)=>new JObject{["slot"]=n,["body"]="NORMAL",["actor"]=slot.IsCargo?"ABSENT":"UP"}))},["targetCategories"]=new JArray(new JObject{["targetId"]="enemy",["category"]="ENEMY"})};
   var composition=new BDirectAttackBuffBinding(i,defs,b,BDirectAttackInput.Digest(b));var loop=new JObject{["version"]=BDirectAttackBasicLoopBinding.Version,["provenance"]="BOUNDED_LOCAL_NOT_FULL_RUN",["compositionHash"]=composition.OriginalHash,["targets"]=new JArray(new JObject{["sourceId"]="op_eve",["targetId"]="enemy"})};return new BDirectAttackBasicLoopBinding(composition,loop,BDirectAttackInput.Digest(loop));
  }
  static void Same(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b),"Original independent input/state preserved");
  [Test] public void OriginalEveBasicUsesHerStatsAndNoOwnSentryOrMiraPassive(){var i=Input();var s=new BDirectAttackSession(i,100);var r=s.ApplyBasicImpact("eve","op_eve","enemy",0);Assert.AreEqual(1368,s.Hp("op_eve"));Assert.AreEqual(25,r.BeforeShield);Same(Q(1939,75),r.Calculation["exact"]);Assert.AreEqual(675,s.Hp("enemy"));Assert.Contains("op_eve:BASIC",i.SupportedActions.ToArray());Assert.IsFalse(i.OperationallyExecutable);File.WriteAllText(Root+"QA/CombatBMigration-20261003/EveBasic/local-original-input.json",i.Capture().ToString());File.WriteAllText(Root+"QA/CombatBMigration-20261003/EveBasic/independent-observation.json",new JObject{["status"]="INDEPENDENT_CANONICAL_EVE_BASIC_NOT_HTTP_PHYSICAL_START",["inputHash"]=i.OriginalHash,["ownedProfileHash"]=BDirectAttackInput.Digest(Owned()),["definitionHash"]=Def().ContentHash,["basicIntervalMs"]=2000,["hp"]=s.Hp("op_eve"),["enemyDefense"]=i.Capture()["entities"].Single(x=>(string)x["id"]=="enemy")["defense"].DeepClone(),["exact"]=r.Calculation["exact"].DeepClone(),["damage"]=r.BeforeShield,["enemyHpAfter"]=s.Hp("enemy"),["eveSentryPassiveAppliedToBasic"]=false,["operatingStart"]=false}.ToString());}
  [Test] public void OriginalTwoSecondBasicPeriodAndExactReplayRemainOwnedByTheExistingClock(){var i=Input();var s=new BDirectAttackSession(i,100);var r=s.ApplyBasicImpact("first","op_eve","enemy",0);Assert.AreSame(r,s.ApplyBasicImpact("first","op_eve","enemy",0));Assert.Throws<InvalidOperationException>(()=>s.ApplyBasicImpact("early","op_eve","enemy",0));s.Advance(19990000,1999);Assert.Throws<InvalidOperationException>(()=>s.ApplyBasicImpact("still-early","op_eve","enemy",1999));s.Advance(10000,1);Assert.AreEqual(25,s.ApplyBasicImpact("second","op_eve","enemy",2000).BeforeShield);var saved=s.CaptureLocal();Assert.AreEqual(V2,(string)JObject.Parse(saved)["schema"]);Same(JObject.Parse(saved),JObject.Parse(BDirectAttackSession.RestoreLocal(saved,i,100).CaptureLocal()));}
  [TestCase("BCB01",28)][TestCase("BCB02",25)] public void OriginalBuffAndNativeAutomaticClockApplyOnceWithoutSentryActions(string type,int damage){var b=LoopBinding(Input(),type);var s=new BDirectAttackBasicLoop(b,1000);var r=s.Advance("batch",40010000,4001);CollectionAssert.AreEqual(new long[]{1,2001,4001},r.Hits.Select(x=>x.Attack.Tick));CollectionAssert.AreEqual(new[]{damage,damage,damage},r.Hits.Select(x=>x.Attack.BeforeShield));Assert.AreEqual(700-damage*3,s.Hp("enemy"));Assert.IsTrue(r.Hits.All(x=>x.Attack.SourceId=="op_eve"));Same(s.Capture(),BDirectAttackBasicLoop.Restore(s.Capture(),b,1000).Capture());}
  [Test] public void LargeAndSplitAdvancesKeepExactEveOriginalState(){var b=LoopBinding(Input());var a=new BDirectAttackBasicLoop(b,1000);var c=new BDirectAttackBasicLoop(b,1000);a.Advance("one",40010000,4001);c.Advance("one",10000,1);c.Advance("two",20000000,2000);c.Advance("three",20000000,2000);foreach(var key in new[]{"allies","enemies","clock","next"})Same(a.Capture()["state"]["direct"][key],c.Capture()["state"]["direct"][key]);Same(a.Capture()["state"]["buffs"],c.Capture()["state"]["buffs"]);Assert.AreEqual(a.Hp("enemy"),c.Hp("enemy"));Assert.AreEqual(a.Tick,c.Tick);}
  [TestCase("legacy")][TestCase("unknown")][TestCase("miraAttack")][TestCase("miraHp")][TestCase("miraPeriod")][TestCase("identity")][TestCase("unsupportedTarget")][TestCase("hash")]
  public void OriginalEveDefinitionStatsIdentityAndNewVersionAreRequired(string part){var p=Packet();var e=Entity(p,"op_eve");if(part=="legacy")p["version"]=BDirectAttackInput.Version;if(part=="unknown")e["definitionId"]="op_sera";if(part=="miraAttack")e["attack"]=Q(2900,100);if(part=="miraHp")e["maxHp"]=1520;if(part=="miraPeriod")e["basicIntervalMicroseconds"]=1800000;if(part=="identity")e["id"]="eve-alias";if(part=="unsupportedTarget")e["allowedTargets"]=new JArray("CARRIAGE");if(part=="hash")Assert.Throws<ArgumentException>(()=>new BDirectAttackInput(p,"bad",Formation(1),Owned(),BDirectAttackInput.Digest(Owned()),Def()));else Assert.Throws<ArgumentException>(()=>Input(p));}
  [Test] public void EveAdjacentSlotEnvelopeRejectsTwoSlotsWithoutInventingGeometry(){var p=Packet(3);Entity(p,"enemy")["slot"]=2;foreach(var g in (JArray)p["geometry"]){if((string)g["sourceId"]=="enemy")g["sourceSlot"]=2;if((string)g["targetId"]=="enemy")g["targetSlot"]=2;}var s=new BDirectAttackSession(Input(p),100);var before=JObject.Parse(s.CaptureLocal());Assert.Throws<InvalidOperationException>(()=>s.ApplyBasicImpact("range","op_eve","enemy",0));Same(before,JObject.Parse(s.CaptureLocal()));}
  [TestCase("ACTIVE")][TestCase("ULTIMATE")][TestCase("SENTRY")]
  public void OnlyBasicIsExplicitlySupported(string ability){var s=new BDirectAttackSession(Input(),100);var before=JObject.Parse(s.CaptureLocal());Assert.Throws<InvalidOperationException>(()=>s.ApplyBasicImpact("unsupported","op_eve","enemy",0,ability));Same(before,JObject.Parse(s.CaptureLocal()));}
  [Test] public void OriginalInputMutationCannotChangeEveStatsOrPassiveScope(){var p=Packet();var i=Input(p);Entity(p,"op_eve")["attack"]=Q(999);i.Capture()["version"]="bad";Assert.AreEqual(25,new BDirectAttackSession(i,100).ApplyBasicImpact("original","op_eve","enemy",0).BeforeShield);}
  static BDirectAttackInput Mira()=> (BDirectAttackInput)typeof(BDirectAttackBasicLoopTests).GetMethod("Input",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{null});
  [Test] public void ExplicitV2MiraKeepsOriginalOwnBasicDamageAndV1History(){var old=Mira();var p=old.Capture();p["version"]=V2;var o=Owned();var newer=new BDirectAttackInput(p,BDirectAttackInput.Digest(p),old.Formation,o,BDirectAttackInput.Digest(o),Def());var a=new BDirectAttackSession(old,100);var b=new BDirectAttackSession(newer,100);var ra=a.ApplyBasicImpact("mira","op_mira","enemy",0);var rb=b.ApplyBasicImpact("mira","op_mira","enemy",0);Same(ra.Calculation,rb.Calculation);Assert.AreEqual(ra.BeforeShield,rb.BeforeShield);Assert.AreEqual(BDirectAttackInput.Version,(string)JObject.Parse(a.CaptureLocal())["schema"]);Assert.AreEqual(V2,(string)JObject.Parse(b.CaptureLocal())["schema"]);Same(JObject.Parse(a.CaptureLocal()),JObject.Parse(BDirectAttackSession.RestoreLocal(a.CaptureLocal(),old,100).CaptureLocal()));}
  [Test] public void ANewEveCacheCannotMasqueradeAsOldMiraInputOrSchema(){var i=Input();var s=new BDirectAttackSession(i,100);s.ApplyBasicImpact("eve","op_eve","enemy",0);var original=JObject.Parse(s.CaptureLocal());var changed=(JObject)original.DeepClone();changed["schema"]=BDirectAttackInput.Version;Assert.Throws<ArgumentException>(()=>BDirectAttackSession.RestoreLocal(changed.ToString(),i,100));Assert.Throws<ArgumentException>(()=>BDirectAttackSession.RestoreLocal(original.ToString(),Mira(),100));Same(original,JObject.Parse(s.CaptureLocal()));}
 }
}
